class Solution {
public:
    int equalPairs(vector<vector<int>>& grid) {
        int n = (int)grid.size();
        struct VecHash {
            size_t operator()(const vector<int>& v) const {
                size_t h = 0;
                for (int x : v) {
                    h ^= (size_t)x + 0x9e3779b9 + (h << 6) + (h >> 2);
                }
                return h;
            }
        };
        unordered_map<vector<int>, int, VecHash> rowCount;
        for (int i = 0; i < n; i++) {
            rowCount[grid[i]]++;
        }
        int ans = 0;
        vector<int> col(n);
        for (int j = 0; j < n; j++) {
            for (int i = 0; i < n; i++) {
                col[i] = grid[i][j];
            }
            auto it = rowCount.find(col);
            if (it != rowCount.end()) {
                ans += it->second;
            }
        }
        return ans;
    }
};
